    if n==0:return ''
    t='^'
    for ch in s:
        t+='#'+ch
    t+='#$'
    N=len(t)
    p=[0]*N
    c=0;r=0
    best_len=0;best_start=0
    for i in range(1,N-1):
        mir=2*c-i
        if i<r:
            p[i]=min(r-i,p[mir])
        while t[i+1+p[i]]==t[i-1-p[i]]:
            p[i]+=1
        if i+p[i]>r:
            c=i;r=i+p[i]
        cur_len=p[i]//2
        cur_start=(i-p[i])//2
        if cur_len>best_len or (cur_len==best_len and cur_start<best_start):
            best_len=cur_len;best_start=cur_start
    return s[best_start:best_start+best_len]

