                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 1
                else:
                    in_q = False
            else:
                cur.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(cur))
                cur = []
            elif ch == '"':
                in_q = True
            else:
                cur.append(ch)
        i += 1
    fields.append(''.join(cur))
