def solve(grid):
    # Count islands of 1s (4-directionally) handling ragged grids.
    if not grid:
        return 0
    n = len(grid)
    # Determine maximum columns across rows
    max_cols = max((len(row) for row in grid), default=0)
    # Pad rows with zeros to make rectangular for easier indexing
    padded = [row + [0] * (max_cols - len(row)) for row in grid]
    visited = [[False] * max_cols for _ in range(n)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < max_cols and not visited[nx][ny] and padded[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for i in range(n):
        for j in range(max_cols):
            if padded[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

