def solve(intervals):
    if not intervals:
        return []
    # Sort by start
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0][:]]
    for start, end in intervals[1:]:
        last = merged[-1]
        if start <= last[1]:  # overlap or touch
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

def solve(line: str):
    import csv
    # csv.reader expects an iterable of lines
    # Use strict quoting rules
    # If line is empty, csv returns [] -> we need ['']
    if line == '':
        return ['']
    reader = csv.reader([line], strict=True)
    return next(reader)

