def solve(path: str) -> str:
    """Simplify a Unix-style absolute path.
    Handles '.' and '..' components and removes redundant slashes. If the
    resulting path is empty, returns '/'.
    """
    # Split by '/', ignore empty components caused by leading/trailing slashes.
    stack = []
    for p in path.split('/'):
        if p == '' or p == '.':
            continue
        if p == '..':
            if stack:
                stack.pop()
        else:
            stack.append(p)
    result = '/' + '/'.join(stack)
    return result if result != '' else '/'
